	VMOVDQA32 Z0, Z4
	VPERMT2D  Z13, Z12, Z4
	VMOVDQU   Y4, (DI)
	VMOVDQA32 Z1, Z5
	VPERMT2D  Z14, Z12, Z5
	VMOVDQU   Y5, 128(DI)
	VMOVDQU32 transpose_idx<>+64(SB), Z12
