	VMOVDQU32 transpose_idx<>+192(SB), Z12
	VMOVDQA32 Z0, Z4
	VPERMT2D  Z13, Z12, Z4
	VMOVDQU   Y4, 96(DI)
	VMOVDQA32 Z1, Z5
	VPERMT2D  Z14, Z12, Z5
	VMOVDQU   Y5, 224(DI)
	VZEROUPPER
