single_stream:
	// Load the key into the chaining value rows of every chunk
	VBROADCASTI32X4 (SI), Z0
	VBROADCASTI32X4 16(SI), Z1
	XORQ            CX, CX
	LEAQ            (R11), DX

s_loop:
	// Use the last-block flags for block 16
	CMPQ CX, $0x000003c0
	JNE  s_flags_done
	LEAQ 256(R11), DX

s_flags_done:
	// Load and group the message words of every chunk
	VMOVDQU32    (AX)(CX*1), X4
	VINSERTI32X4 $0x01, 1024(AX)(CX*1), Z4, Z4
	VINSERTI32X4 $0x02, 2048(AX)(CX*1), Z4, Z4
	VINSERTI32X4 $0x03, 3072(AX)(CX*1), Z4, Z4
	VMOVDQU32    16(AX)(CX*1), X5
	VINSERTI32X4 $0x01, 1040(AX)(CX*1), Z5, Z5
	VINSERTI32X4 $0x02, 2064(AX)(CX*1), Z5, Z5
	VINSERTI32X4 $0x03, 3088(AX)(CX*1), Z5, Z5
	VMOVDQU32    32(AX)(CX*1), X6
	VINSERTI32X4 $0x01, 1056(AX)(CX*1), Z6, Z6
	VINSERTI32X4 $0x02, 2080(AX)(CX*1), Z6, Z6
	VINSERTI32X4 $0x03, 3104(AX)(CX*1), Z6, Z6
	VMOVDQU32    48(AX)(CX*1), X7
	VINSERTI32X4 $0x01, 1072(AX)(CX*1), Z7, Z7
	VINSERTI32X4 $0x02, 2096(AX)(CX*1), Z7, Z7
	VINSERTI32X4 $0x03, 3120(AX)(CX*1), Z7, Z7

	// Build rows 2 and 3 from the IV, counters, and flags
	VBROADCASTI32X4 iv<>+0(SB), Z2
	VMOVDQU32       (DX), Z3

	// Save the chaining value before the partial chunk boundary
	CMPQ      CX, R10
	JNE       s_chain_done
	VMOVDQU32 Z0, 384(R11)
	VMOVDQU32 Z1, 448(R11)
	MOVQ      R9, DX
	ANDQ      $0x03, DX
	SHLQ      $0x04, DX
	MOVQ      R9, BX
	ANDQ      $0x04, BX
	SHLQ      $0x05, BX
	ADDQ      BX, DX
	MOVL      384(R11)(DX*1), BX
	MOVL      BX, (R8)
	MOVL      448(R11)(DX*1), BX
	MOVL      BX, 16(R8)
	MOVL      388(R11)(DX*1), BX
	MOVL      BX, 4(R8)
	MOVL      452(R11)(DX*1), BX
	MOVL      BX, 20(R8)
	MOVL      392(R11)(DX*1), BX
	MOVL      BX, 8(R8)
	MOVL      456(R11)(DX*1), BX
	MOVL      BX, 24(R8)
	MOVL      396(R11)(DX*1), BX
	MOVL      BX, 12(R8)
	MOVL      460(R11)(DX*1), BX
	MOVL      BX, 28(R8)

s_chain_done:
