// Requires: AVX, AVX2, AVX512F
TEXT ·HashF16(SB), $2832-64
	MOVQ input+0(FP), AX
	MOVQ length+8(FP), CX
	MOVQ counter+16(FP), DX
	MOVL flags+24(FP), BX
	MOVQ key+32(FP), SI
	MOVQ outLo+40(FP), DI
