	VPUNPCKLDQ   Y0, Y2, Y1
	VPUNPCKHDQ   Y0, Y2, Y0
	VPERMQ       $0xd8, Y1, Y1
	VPERMQ       $0xd8, Y0, Y0
	VMOVDQU      Y1, 2560(R12)
	VMOVDQU      Y0, 2624(R12)
	VPBROADCASTQ 2760(R12), Y0
	VPADDQ       counter<>+64(SB), Y0, Y0
	VPBROADCASTQ 2760(R12), Y1
	VPADDQ       counter<>+96(SB), Y1, Y1
	VPUNPCKLDQ   Y1, Y0, Y2
	VPUNPCKHDQ   Y1, Y0, Y0
	VPUNPCKLDQ   Y0, Y2, Y1
	VPUNPCKHDQ   Y0, Y2, Y0
	VPERMQ       $0xd8, Y1, Y1
	VPERMQ       $0xd8, Y0, Y0
